{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "A high-transfer PET analogue reached 5–6% of injected dose in monkey brain, demonstrating robust BBB permeation after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "In humans, the high-transfer radioligand AZ10419369 showed rapid, high brain uptake despite being an ABC-transporter substrate in rodents, indicating that efflux liability does not preclude meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A structurally related amide-rich heteroaromatic compound achieved brain concentrations higher than plasma in rats, directly supporting CNS penetration for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "An iodinated aromatic radioligand, AM281, readily permeates the human BBB, providing direct evidence that iodine-substituted analogues can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rodent PET data for AZ10419369 show low baseline brain uptake that increases markedly after ABC-transporter inhibition, confirming an efflux liability that may also apply to the query but is not decisive against adequate net CNS exposure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer direct in vivo PET, brain/plasma, and human CSF measurements consistently support meaningful CNS access for the query, despite a physicochemical prior suggesting low passive permeability and possible efflux. The main caveat is transporter-mediated efflux seen in rodents, but higher-species and human data show adequate net brain uptake.",
  "evidence_gaps": [
    "No direct brain or CSF measurement exists for the exact query molecule.",
    "The extent of unbound brain exposure relative to plasma is not quantified for the query.",
    "The impact of the query's high molecular weight and TPSA on passive permeability is inferred only from physicochemical priors, not direct experimental data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

